 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append(cells)

    for cells in components:
        colors = {}
        for r, c in cells:
            colors.setdefault(grid[r][c], []).append((r, c))
        # Nested layers are ordered by the bounding-box area of each color.
        ordered = sorted(colors, key=lambda k: -(
            (max(r for r, _ in colors[k]) - min(r for r, _ in colors[k]) + 1)
            * (max(c for _, c in colors[k]) - min(c for _, c in colors[k]) + 1)
        ))
        reversed_colors = ordered[::-1]
        for source, target in zip(ordered, reversed_colors):
            for r, c in colors[source]:
                out[r][c] = target
    return out
